import type { ContentPack } from '../types';
import { lesson, M, Nq, TF } from '../lib';

const P: ContentPack = {
  '1E-BG-1': lesson(['La biología y la geología avanzan con el trabajo de muchas personas: Darwin (evolución), Mendel (herencia), Ramón y Cajal (neuronas), Rachel Carson (ecología), Jane Goodall (chimpancés), Marie Tharp (mapas del fondo marino).|La biologia i la geologia avancen amb el treball de moltes persones: Darwin (evolució), Mendel (herència), Ramón y Cajal (neurones), Rachel Carson (ecologia), Jane Goodall (ximpanzés), Marie Tharp (mapes del fons marí).|Biology and geology advance through the work of many people: Darwin (evolution), Mendel (heredity), Ramón y Cajal (neurons), Rachel Carson (ecology), Jane Goodall (chimpanzees), Marie Tharp (maps of the ocean floor).'],
    '¿Quién estudió durante décadas a los chimpancés en libertad?|Qui va estudiar durant dècades els ximpanzés en llibertat?|Who studied wild chimpanzees for decades?', ['Observó que usan herramientas.|Va observar que usen eines.|She saw that they use tools.', 'Jane Goodall.|Jane Goodall.|Jane Goodall.'], [
      M('¿Quién propuso la teoría de la evolución por selección natural?|Qui va proposar la teoria de l’evolució per selecció natural?|Who proposed the theory of evolution by natural selection?', 'Charles Darwin|Charles Darwin|Charles Darwin', ['Isaac Newton|Isaac Newton|Isaac Newton', 'Louis Pasteur|Louis Pasteur|Louis Pasteur'], 'Viajó en el Beagle.|Va viatjar en el Beagle.|He sailed on the Beagle.'),
      M('Santiago Ramón y Cajal, premio Nobel español, estudió…|Santiago Ramón y Cajal, premi Nobel espanyol, va estudiar…|Santiago Ramón y Cajal, a Spanish Nobel laureate, studied…', 'las neuronas|les neurones|neurons', ['los volcanes|els volcans|volcanoes', 'las estrellas|les estreles|stars'], 'Dibujó el sistema nervioso con detalle.|Va dibuixar el sistema nerviós amb detall.|He drew the nervous system in detail.'),
      M('Rachel Carson alertó con su libro Primavera silenciosa sobre…|Rachel Carson va alertar amb el seu llibre Primavera silenciosa sobre…|Rachel Carson’s book Silent Spring warned about…', 'los pesticidas|els pesticides|pesticides', ['los terremotos|els terratrémols|earthquakes', 'los planetas|els planetes|the planets'], 'Dañaban aves y ecosistemas.|Danyaven ocells i ecosistemes.|They harmed birds and ecosystems.'),
      M('Marie Tharp cartografió…|Marie Tharp va cartografiar…|Marie Tharp mapped…', 'el fondo del océano|el fons de l’oceà|the ocean floor', ['la Luna|la Lluna|the Moon', 'el cerebro|el cervell|the brain'], 'Sus mapas apoyaron la tectónica de placas.|Els seus mapes van donar suport a la tectònica de plaques.|Her maps supported plate tectonics.'),
      M('Gregor Mendel descubrió las leyes de…|Gregor Mendel va descobrir les lleis de…|Gregor Mendel discovered the laws of…', 'la herencia|l’herència|heredity', ['la gravedad|la gravetat|gravity', 'la electricidad|l’electricitat|electricity'], 'Cruzó guisantes.|Va creuar pésols.|He crossed pea plants.'),
      TF('El trabajo científico es colectivo: se basa en lo que descubrieron otros.|El treball científic és col·lectiu: es basa en el que van descobrir altres.|Scientific work is collective: it builds on what others discovered.', true, '«A hombros de gigantes».|«A espatles de gegants».|"On the shoulders of giants".'),
    ]),
  '1E-BG-2': lesson(['El método científico: observación, pregunta, hipótesis, experimentación (cambiando una sola variable), análisis de resultados y conclusión. Los resultados se comunican para que otros los comprueben.|El mètode científic: observació, pregunta, hipòtesi, experimentació (canviant una sola variable), anàlisi de resultats i conclusió. Els resultats es comuniquen perquè altres els comproven.|The scientific method: observation, question, hypothesis, experiment (changing only one variable), analysis of results and conclusion. Results are shared so others can check them.'],
    'Las judías crecen más en la ventana. ¿Hipótesis?|Els fesols creixen més en la finestra. Hipòtesi?|Beans grow more by the window. Hypothesis?', ['Una posible explicación comprobable.|Una possible explicació comprovable.|A testable possible explanation.', '«Las plantas crecen más con más luz».|«Les plantes creixen més amb més llum».|"Plants grow more with more light".'], [
      M('¿Qué paso va primero?|Quin pas va primer?|Which step comes first?', 'observar|observar|observing', ['concluir|concloure|concluding', 'experimentar|experimentar|experimenting'], 'Todo empieza con algo que nos llama la atención.|Tot comença amb alguna cosa que ens crida l’atenció.|It all starts with noticing something.'),
      M('En un experimento, el grupo de control…|En un experiment, el grup de control…|In an experiment, the control group…', 'no recibe el cambio que se estudia|no rep el canvi que s’estudia|does not get the change being tested', ['recibe el doble|rep el doble|gets double', 'no se mide|no es mesura|is not measured'], 'Sirve para comparar.|Servix per a comparar.|It is used for comparison.'),
      TF('Una hipótesis debe poder comprobarse.|Una hipòtesi s’ha de poder comprovar.|A hypothesis must be testable.', true, 'Si no, no es científica.|Si no, no és científica.|Otherwise it is not scientific.'),
      M('Para saber si el abono ayuda a crecer, ¿qué cambias?|Per a saber si l’adob ajuda a créixer, què canvies?|To find out if fertiliser helps growth, what do you change?', 'solo la cantidad de abono|només la quantitat d’adob|only the amount of fertiliser', ['abono, luz y agua a la vez|adob, llum i aigua alhora|fertiliser, light and water together', 'nada|res|nothing'], 'Una sola variable.|Una sola variable.|One variable only.'),
      M('Los datos de un experimento se organizan en…|Les dades d’un experiment s’organitzen en…|Experimental data is organised in…', 'tablas y gráficas|taules i gràfiques|tables and graphs', ['poemas|poemes|poems', 'mapas del tiempo|mapes del temps|weather maps'], 'Facilitan ver patrones.|Faciliten veure patrons.|They make patterns easier to see.'),
      TF('Si un experimento sale distinto de lo esperado, hay que cambiar los datos.|Si un experiment ix diferent del que s’esperava, cal canviar les dades.|If an experiment gives unexpected results, you should change the data.', false, 'Los datos no se inventan; se revisa la hipótesis.|Les dades no s’inventen; es revisa la hipòtesi.|Data is never made up; revise the hypothesis.'),
    ]),
  '1E-BG-3': lesson(['En el laboratorio: bata, gafas y pelo recogido; no comer ni beber; leer las etiquetas y los pictogramas; avisar de cualquier accidente. Material común: microscopio, lupa, probeta, vaso de precipitados, placa de Petri, mechero.|Al laboratori: bata, ulleres i cabells recollits; no menjar ni beure; llegir les etiquetes i els pictogrames; avisar de qualsevol accident. Material comú: microscopi, lupa, proveta, got de precipitats, placa de Petri, encenedor.|In the lab: lab coat, goggles and hair tied back; no eating or drinking; read labels and hazard symbols; report any accident. Common equipment: microscope, hand lens, measuring cylinder, beaker, Petri dish, Bunsen burner.'],
    'Se te cae ácido en la mano. ¿Qué haces?|Et cau àcid en la mà. Què fas?|You spill acid on your hand. What do you do?', ['Avisar al profesor.|Avisar el professor.|Tell the teacher.', 'Lavar con mucha agua.|Llavar amb molta aigua.|Rinse with plenty of water.'], [
      M('Para observar células se usa…|Per a observar cèl·lules s’usa…|To look at cells you use…', 'el microscopio|el microscopi|a microscope', ['la probeta|la proveta|a measuring cylinder', 'la balanza|la balança|a balance'], 'Aumenta cientos de veces.|Augmenta centenars de vegades.|It magnifies hundreds of times.'),
      Nq('Ocular ×10 y objetivo ×40. ¿Aumento total?|Ocular ×10 i objectiu ×40. Augment total?|Eyepiece ×10 and objective ×40. Total magnification?', 400, [50, 40, 4000], 'Se multiplican.|Es multipliquen.|Multiply them.'),
      M('¿Qué no se debe hacer en el laboratorio?|Què no s’ha de fer al laboratori?|What must you not do in the lab?', 'oler directamente los productos|olorar directament els productes|sniff chemicals directly', ['llevar gafas|portar ulleres|wear goggles', 'lavarse las manos|llavar-se les mans|wash your hands'], 'Algunos vapores son tóxicos.|Alguns vapors són tòxics.|Some fumes are toxic.'),
      M('Para cultivar bacterias se usa…|Per a cultivar bacteris s’usa…|To grow bacteria you use…', 'una placa de Petri|una placa de Petri|a Petri dish', ['un embudo|un embut|a funnel', 'un termómetro|un termòmetre|a thermometer'], 'Con un medio nutritivo.|Amb un medi nutritiu.|With a nutrient medium.'),
      TF('Hay que recogerse el pelo largo cerca de un mechero.|Cal recollir-se els cabells llargs prop d’un encenedor.|Long hair should be tied back near a burner.', true, 'Puede arder.|Pot cremar.|It could catch fire.'),
      M('La lupa binocular sirve para ver…|La lupa binocular servix per a veure…|A stereo microscope is used to see…', 'objetos pequeños en relieve, como insectos|objectes xicotets en relleu, com insectes|small objects in 3D, such as insects', ['células por dentro|cèl·lules per dins|inside cells', 'estrellas|estreles|stars'], 'Aumenta menos que el microscopio.|Augmenta menys que el microscopi.|It magnifies less than a microscope.'),
    ]),
  '1E-BG-4': lesson(['Para buscar información científica: usa palabras clave, contrasta varias fuentes fiables (universidades, museos, organismos oficiales), mira la fecha y el autor y cita siempre las fuentes. Para comunicar: informes, presentaciones, carteles o vídeos claros.|Per a buscar informació científica: usa paraules clau, contrasta diverses fonts fiables (universitats, museus, organismes oficials), mira la data i l’autor i cita sempre les fonts. Per a comunicar: informes, presentacions, cartells o vídeos clars.|To find scientific information: use keywords, compare several reliable sources (universities, museums, official bodies), check the date and author, and always cite your sources. To communicate: clear reports, presentations, posters or videos.'],
    '¿Qué fuente es más fiable sobre el lince ibérico?|Quina font és més fiable sobre el linx ibèric?|Which source is more reliable about the Iberian lynx?', ['La web de un organismo de conservación.|La web d’un organisme de conservació.|A conservation body’s website.', 'Mejor que un comentario anónimo en una red social.|Millor que un comentari anònim en una xarxa social.|Better than an anonymous social media comment.'], [
      TF('Hay que citar de dónde sacamos la información.|Cal citar d’on traiem la informació.|We must say where we got our information.', true, 'Es honesto y permite comprobarla.|És honest i permet comprovar-la.|It is honest and lets others check it.'),
      M('¿Qué dato ayuda a valorar una página web?|Quina dada ajuda a valorar una pàgina web?|What helps you judge a website?', 'quién la escribe y cuándo|qui l’escriu i quan|who wrote it and when', ['el color del fondo|el color del fons|the background colour', 'el número de anuncios|el nombre d’anuncis|the number of adverts'], 'Autoría y fecha.|Autoria i data.|Author and date.'),
      M('Para buscar mejor en Internet, usa…|Per a buscar millor en Internet, usa…|To search better online, use…', 'palabras clave precisas|paraules clau precises|precise keywords', ['frases muy largas|frases molt llargues|very long sentences', 'solo emojis|només emojis|only emojis'], 'Por ejemplo: «lince ibérico población 2024».|Per exemple: «linx ibèric població 2024».|For example: "Iberian lynx population 2024".'),
      TF('Copiar y pegar un texto sin citar es plagio.|Copiar i apegar un text sense citar és plagi.|Copying and pasting text without citing it is plagiarism.', true, 'Explica con tus palabras y cita.|Explica amb les teues paraules i cita.|Explain in your own words and cite.'),
      M('Antes de compartir una noticia científica sorprendente…|Abans de compartir una notícia científica sorprenent…|Before sharing a surprising science story…', 'compruébala en otras fuentes fiables|comprova-la en altres fonts fiables|check it in other reliable sources', ['compártela rápido|comparteix-la ràpid|share it quickly', 'cambia el titular|canvia el titular|change the headline'], 'Puede ser un bulo.|Pot ser un bulo.|It may be a hoax.'),
      M('Una buena presentación científica tiene…|Una bona presentació científica té…|A good science presentation has…', 'poco texto, imágenes claras y fuentes|poc text, imatges clares i fonts|little text, clear images and sources', ['mucho texto pequeño|molt de text xicotet|lots of small text', 'sin conclusiones|sense conclusions|no conclusions'], 'Que se entienda de un vistazo.|Que s’entenga d’un colp d’ull.|Easy to follow at a glance.'),
    ]),
  '1E-BG-5': lesson(['Un ser vivo realiza tres funciones vitales: nutrición (obtener materia y energía), relación (percibir el medio y responder) y reproducción (originar nuevos individuos). Además, está formado por células y tiene una composición química propia (bioelementos y biomoléculas).|Un ésser viu realitza tres funcions vitals: nutrició (obtindre matèria i energia), relació (percebre el medi i respondre) i reproducció (originar nous individus). A més, està format per cèl·lules i té una composició química pròpia (bioelements i biomolècules).|A living thing carries out three life functions: nutrition (getting matter and energy), interaction (sensing and responding to its surroundings) and reproduction (producing new individuals). It is also made of cells and has its own chemical make-up (bioelements and biomolecules).'],
    '¿Es un ser vivo una semilla?|És un ésser viu una llavor?|Is a seed a living thing?', ['Tiene células y un embrión en reposo.|Té cèl·lules i un embrió en repòs.|It has cells and a resting embryo.', 'Sí: puede germinar y crecer.|Sí: pot germinar i créixer.|Yes: it can germinate and grow.'], [
      M('¿Qué función vital es girar hacia la luz una planta?|Quina funció vital és girar cap a la llum una planta?|Which life function is a plant turning towards light?', 'relación|relació|interaction', ['nutrición|nutrició|nutrition', 'reproducción|reproducció|reproduction'], 'Percibe y responde a un estímulo.|Percep i respon a un estímul.|It senses and responds to a stimulus.'),
      M('¿Cuál NO es un ser vivo?|Quin NO és un ésser viu?|Which is NOT a living thing?', 'una roca|una roca|a rock', ['un hongo|un fong|a fungus', 'una bacteria|un bacteri|a bacterium'], 'No se nutre, ni se relaciona, ni se reproduce.|No es nodrix, ni es relaciona, ni es reproduïx.|It does not feed, respond or reproduce.'),
      M('Los bioelementos más abundantes en los seres vivos son…|Els bioelements més abundants en els éssers vius són…|The most abundant bioelements in living things are…', 'C, H, O y N|C, H, O i N|C, H, O and N', ['Fe, Au y Ag|Fe, Au i Ag|Fe, Au and Ag', 'He y Ne|He i Ne|He and Ne'], 'Carbono, hidrógeno, oxígeno y nitrógeno.|Carboni, hidrogen, oxigen i nitrogen.|Carbon, hydrogen, oxygen and nitrogen.'),
      M('¿Qué biomolécula es la más abundante en los seres vivos?|Quina biomolècula és la més abundant en els éssers vius?|Which biomolecule is the most abundant in living things?', 'el agua|l’aigua|water', ['el azúcar|el sucre|sugar', 'la grasa|el greix|fat'], 'Más de la mitad de nuestro peso.|Més de la meitat del nostre pes.|More than half our body weight.'),
      TF('Los virus no tienen células, por eso se discute si son seres vivos.|Els virus no tenen cèl·lules, per això es discutix si són éssers vius.|Viruses have no cells, which is why it is debated whether they are alive.', true, 'Solo se reproducen dentro de células.|Només es reproduïxen dins de cèl·lules.|They only reproduce inside cells.'),
      M('Comer y respirar forman parte de la función de…|Menjar i respirar formen part de la funció de…|Eating and breathing are part of…', 'nutrición|nutrició|nutrition', ['relación|relació|interaction', 'reproducción|reproducció|reproduction'], 'Obtener materia y energía.|Obtindre matèria i energia.|Getting matter and energy.'),
    ]),
  '1E-BG-6': lesson(['La célula es la unidad de vida. Partes: membrana, citoplasma y material genético. Procariota: sin núcleo (bacterias). Eucariota: con núcleo; puede ser animal o vegetal (con pared celular, cloroplastos y una gran vacuola).|La cèl·lula és la unitat de vida. Parts: membrana, citoplasma i material genètic. Procariota: sense nucli (bacteris). Eucariota: amb nucli; pot ser animal o vegetal (amb paret cel·lular, cloroplasts i un gran vacúol).|The cell is the unit of life. Parts: membrane, cytoplasm and genetic material. Prokaryotic: no nucleus (bacteria). Eukaryotic: has a nucleus; can be animal or plant (with a cell wall, chloroplasts and a large vacuole).'],
    'Una célula con núcleo, pared y cloroplastos, ¿de qué tipo es?|Una cèl·lula amb nucli, paret i cloroplasts, de quin tipus és?|A cell with a nucleus, a wall and chloroplasts: what type is it?', ['Tiene núcleo: eucariota.|Té nucli: eucariota.|It has a nucleus: eukaryotic.', 'Pared y cloroplastos: vegetal.|Paret i cloroplasts: vegetal.|Wall and chloroplasts: plant.'], [
      M('Las bacterias son células…|Els bacteris són cèl·lules…|Bacteria are…', 'procariotas|procariotes|prokaryotic cells', ['eucariotas vegetales|eucariotes vegetals|plant cells', 'eucariotas animales|eucariotes animals|animal cells'], 'No tienen núcleo.|No tenen nucli.|They have no nucleus.'),
      M('¿Qué orgánulo produce energía en la respiración celular?|Quin orgànul produïx energia en la respiració cel·lular?|Which organelle releases energy in cellular respiration?', 'la mitocondria|el mitocondri|the mitochondrion', ['el cloroplasto|el cloroplast|the chloroplast', 'la pared celular|la paret cel·lular|the cell wall'], 'La «central energética» de la célula.|La «central energètica» de la cèl·lula.|The cell’s "power station".'),
      M('¿Qué orgánulo hace la fotosíntesis?|Quin orgànul fa la fotosíntesi?|Which organelle carries out photosynthesis?', 'el cloroplasto|el cloroplast|the chloroplast', ['la mitocondria|el mitocondri|the mitochondrion', 'el núcleo|el nucli|the nucleus'], 'Contiene clorofila.|Conté clorofil·la.|It contains chlorophyll.'),
      TF('Las células animales tienen pared celular.|Les cèl·lules animals tenen paret cel·lular.|Animal cells have a cell wall.', false, 'Solo membrana; la pared es de plantas, hongos y bacterias.|Només membrana; la paret és de plantes, fongs i bacteris.|Only a membrane; walls are in plants, fungi and bacteria.'),
      M('¿Dónde está el ADN en una célula eucariota?|On està l’ADN en una cèl·lula eucariota?|Where is the DNA in a eukaryotic cell?', 'en el núcleo|en el nucli|in the nucleus', ['en la membrana|en la membrana|in the membrane', 'en la pared|en la paret|in the wall'], 'Controla la célula.|Controla la cèl·lula.|It controls the cell.'),
      M('¿Qué parte controla lo que entra y sale de la célula?|Quina part controla el que entra i ix de la cèl·lula?|Which part controls what enters and leaves the cell?', 'la membrana plasmática|la membrana plasmàtica|the cell membrane', ['el citoplasma|el citoplasma|the cytoplasm', 'la vacuola|el vacúol|the vacuole'], 'Es selectiva.|És selectiva.|It is selective.'),
    ]),
  '1E-BG-7': lesson(['Nutrición autótrofa: el ser vivo fabrica su materia orgánica a partir de inorgánica (agua, CO₂, sales) con energía de la luz: fotosíntesis (plantas, algas). Nutrición heterótrofa: toma materia orgánica ya hecha comiendo otros seres vivos (animales, hongos, muchas bacterias).|Nutrició autòtrofa: l’ésser viu fabrica la seua matèria orgànica a partir d’inorgànica (aigua, CO₂, sals) amb energia de la llum: fotosíntesi (plantes, algues). Nutrició heteròtrofa: pren matèria orgànica ja feta menjant altres éssers vius (animals, fongs, molts bacteris).|Autotrophic nutrition: the organism makes its own organic matter from inorganic matter (water, CO₂, minerals) using light energy: photosynthesis (plants, algae). Heterotrophic nutrition: it takes ready-made organic matter by eating other living things (animals, fungi, many bacteria).', 'Fotosíntesis: CO₂ + agua + luz → glucosa + oxígeno.|Fotosíntesi: CO₂ + aigua + llum → glucosa + oxigen.|Photosynthesis: CO₂ + water + light → glucose + oxygen.'],
    '¿Un champiñón es autótrofo o heterótrofo?|Un xampinyó és autòtrof o heteròtrof?|Is a mushroom autotrophic or heterotrophic?', ['No tiene clorofila.|No té clorofil·la.|It has no chlorophyll.', 'Heterótrofo: se alimenta de materia orgánica del suelo.|Heteròtrof: s’alimenta de matèria orgànica del sòl.|Heterotrophic: it feeds on organic matter in the soil.'], [
      M('¿Qué gas desprenden las plantas en la fotosíntesis?|Quin gas desprenen les plantes en la fotosíntesi?|Which gas do plants give off in photosynthesis?', 'oxígeno|oxigen|oxygen', ['dióxido de carbono|diòxid de carboni|carbon dioxide', 'nitrógeno|nitrogen|nitrogen'], 'El que respiramos.|El que respirem.|The one we breathe.'),
      M('¿Qué necesitan las plantas para la fotosíntesis?|Què necessiten les plantes per a la fotosíntesi?|What do plants need for photosynthesis?', 'luz, agua y CO₂|llum, aigua i CO₂|light, water and CO₂', ['oscuridad y oxígeno|foscor i oxigen|darkness and oxygen', 'solo abono|només adob|only fertiliser'], 'Y clorofila.|I clorofil·la.|And chlorophyll.'),
      M('Un león tiene nutrición…|Un lleó té nutrició…|A lion has…', 'heterótrofa|heteròtrofa|heterotrophic nutrition', ['autótrofa|autòtrofa|autotrophic nutrition', 'fotosintética|fotosintètica|photosynthetic nutrition'], 'Come otros animales.|Menja altres animals.|It eats other animals.'),
      TF('Las plantas también respiran, de día y de noche.|Les plantes també respiren, de dia i de nit.|Plants also respire, day and night.', true, 'Usan oxígeno para obtener energía.|Usen oxigen per a obtindre energia.|They use oxygen to release energy.'),
      M('Las algas tienen nutrición…|Les algues tenen nutrició…|Algae have…', 'autótrofa|autòtrofa|autotrophic nutrition', ['heterótrofa|heteròtrofa|heterotrophic nutrition', 'parásita|paràsita|parasitic nutrition'], 'Hacen la fotosíntesis.|Fan la fotosíntesi.|They photosynthesise.'),
      M('¿Qué sustancia fabrica la planta en la fotosíntesis?|Quina substància fabrica la planta en la fotosíntesi?|What substance does a plant make in photosynthesis?', 'glucosa|glucosa|glucose', ['proteína animal|proteïna animal|animal protein', 'petróleo|petroli|crude oil'], 'Un azúcar que le da energía.|Un sucre que li dona energia.|A sugar that gives it energy.'),
    ]),
  '1E-BG-8': lesson(['Niveles de organización: átomo → molécula → célula → tejido → órgano → aparato o sistema → organismo. Y, fuera del individuo: población → comunidad → ecosistema → biosfera.|Nivells d’organització: àtom → molècula → cèl·lula → teixit → òrgan → aparell o sistema → organisme. I, fora de l’individu: població → comunitat → ecosistema → biosfera.|Levels of organisation: atom → molecule → cell → tissue → organ → organ system → organism. Beyond the individual: population → community → ecosystem → biosphere.'],
    '¿Qué nivel es el corazón?|Quin nivell és el cor?|What level is the heart?', ['Está formado por varios tejidos.|Està format per diversos teixits.|It is made of several tissues.', 'Es un órgano.|És un òrgan.|It is an organ.'], [
      M('Un grupo de células iguales que hacen la misma función es…|Un grup de cèl·lules iguals que fan la mateixa funció és…|A group of similar cells doing the same job is…', 'un tejido|un teixit|a tissue', ['un órgano|un òrgan|an organ', 'una población|una població|a population'], 'Por ejemplo, el tejido muscular.|Per exemple, el teixit muscular.|For example, muscle tissue.'),
      M('Todos los flamencos de L’Albufera forman…|Tots els flamencs de l’Albufera formen…|All the flamingos at L’Albufera form…', 'una población|una població|a population', ['una comunidad|una comunitat|a community', 'un tejido|un teixit|a tissue'], 'Misma especie, mismo lugar.|Mateixa espècie, mateix lloc.|Same species, same place.'),
      M('¿Qué nivel incluye a todos los seres vivos de la Tierra?|Quin nivell inclou tots els éssers vius de la Terra?|Which level includes all living things on Earth?', 'la biosfera|la biosfera|the biosphere', ['el ecosistema|l’ecosistema|the ecosystem', 'la comunidad|la comunitat|the community'], 'Bio = vida.|Bio = vida.|Bio = life.'),
      M('Ordena de menor a mayor:|Ordena de menor a major:|Order from smallest to largest:', 'célula, tejido, órgano, aparato|cèl·lula, teixit, òrgan, aparell|cell, tissue, organ, organ system', ['órgano, célula, aparato, tejido|òrgan, cèl·lula, aparell, teixit|organ, cell, system, tissue', 'tejido, aparato, célula, órgano|teixit, aparell, cèl·lula, òrgan|tissue, system, cell, organ'], 'Cada nivel agrupa al anterior.|Cada nivell agrupa l’anterior.|Each level groups the one before.'),
      TF('Una bacteria es un organismo formado por una sola célula.|Un bacteri és un organisme format per una sola cèl·lula.|A bacterium is an organism made of a single cell.', true, 'Unicelular.|Unicel·lular.|Single-celled.'),
      M('El aparato digestivo está formado por…|L’aparell digestiu està format per…|The digestive system is made of…', 'varios órganos que trabajan juntos|diversos òrgans que treballen junts|several organs working together', ['un solo tejido|un sol teixit|a single tissue', 'una sola célula|una sola cèl·lula|a single cell'], 'Boca, estómago, intestinos…|Boca, estómac, intestins…|Mouth, stomach, intestines…'),
    ]),
  '1E-BG-9': lesson(['Clasificar es agrupar los seres vivos según sus parecidos. Categorías de mayor a menor: dominio, reino, filo, clase, orden, familia, género y especie. Cada especie tiene un nombre científico de dos palabras (Linneo): Homo sapiens, Lynx pardinus.|Classificar és agrupar els éssers vius segons les seues semblances. Categories de major a menor: domini, regne, fílum, classe, ordre, família, gènere i espècie. Cada espècie té un nom científic de dues paraules (Linné): Homo sapiens, Lynx pardinus.|Classifying means grouping living things by their similarities. Categories from largest to smallest: domain, kingdom, phylum, class, order, family, genus and species. Each species has a two-word scientific name (Linnaeus): Homo sapiens, Lynx pardinus.'],
    '¿Qué indica cada palabra de Lynx pardinus?|Què indica cada paraula de Lynx pardinus?|What does each word in Lynx pardinus mean?', ['Lynx es el género.|Lynx és el gènere.|Lynx is the genus.', 'pardinus, la especie (el lince ibérico).|pardinus, l’espècie (el linx ibèric).|pardinus is the species (Iberian lynx).'], [
      M('¿Qué categoría es la más pequeña?|Quina categoria és la més xicoteta?|Which category is the smallest?', 'especie|espècie|species', ['reino|regne|kingdom', 'familia|família|family'], 'Individuos que pueden tener descendencia fértil.|Individus que poden tindre descendència fèrtil.|Individuals that can have fertile offspring.'),
      M('¿Quién creó la nomenclatura binomial?|Qui va crear la nomenclatura binomial?|Who created binomial naming?', 'Linneo|Linné|Linnaeus', ['Darwin|Darwin|Darwin', 'Mendel|Mendel|Mendel'], 'Siglo XVIII.|Segle XVIII.|18th century.'),
      TF('El nombre científico es igual en todos los idiomas.|El nom científic és igual en tots els idiomes.|A scientific name is the same in every language.', true, 'Evita confusiones.|Evita confusions.|It avoids confusion.'),
      M('Dos seres de la misma especie…|Dos éssers de la mateixa espècie…|Two members of the same species…', 'pueden tener hijos fértiles|poden tindre fills fèrtils|can have fertile offspring', ['viven siempre juntos|viuen sempre junts|always live together', 'son del mismo color|són del mateix color|are the same colour'], 'Es la definición de especie.|És la definició d’espècie.|That defines a species.'),
      M('Ordena de mayor a menor:|Ordena de major a menor:|Order from largest to smallest:', 'reino, clase, género, especie|regne, classe, gènere, espècie|kingdom, class, genus, species', ['especie, género, clase, reino|espècie, gènere, classe, regne|species, genus, class, kingdom', 'clase, reino, especie, género|classe, regne, espècie, gènere|class, kingdom, species, genus'], 'Del grupo más amplio al más concreto.|Del grup més ampli al més concret.|From the widest group to the most specific.'),
      M('¿Cómo se escribe correctamente el nombre científico del ser humano?|Com s’escriu correctament el nom científic de l’ésser humà?|How is the human scientific name written correctly?', 'Homo sapiens|Homo sapiens|Homo sapiens', ['homo Sapiens|homo Sapiens|homo Sapiens', 'HOMO SAPIENS|HOMO SAPIENS|HOMO SAPIENS'], 'Género con mayúscula; especie en minúscula; en cursiva.|Gènere amb majúscula; espècie en minúscula; en cursiva.|Genus capitalised, species lower case, in italics.'),
    ]),
  '1E-BG-10': lesson(['Tres dominios: Bacteria, Archaea (procariotas) y Eukarya (eucariotas). Los eucariotas se dividen en reinos: protoctistas (protozoos y algas), hongos, plantas y animales.|Tres dominis: Bacteria, Archaea (procariotes) i Eukarya (eucariotes). Els eucariotes es dividixen en regnes: protoctists (protozous i algues), fongs, plantes i animals.|Three domains: Bacteria, Archaea (prokaryotes) and Eukarya (eukaryotes). Eukaryotes are divided into kingdoms: protists (protozoa and algae), fungi, plants and animals.'],
    'Un ser pluricelular, heterótrofo, con pared de quitina. ¿Reino?|Un ésser pluricel·lular, heteròtrof, amb paret de quitina. Regne?|A many-celled heterotroph with chitin cell walls. Kingdom?', ['No hace fotosíntesis y tiene pared.|No fa fotosíntesi i té paret.|It does not photosynthesise and has walls.', 'Hongos.|Fongs.|Fungi.'], [
      M('¿Qué reino tiene seres autótrofos pluricelulares con tejidos?|Quin regne té éssers autòtrofs pluricel·lulars amb teixits?|Which kingdom has many-celled autotrophs with tissues?', 'plantas|plantes|plants', ['hongos|fongs|fungi', 'animales|animals|animals'], 'Hacen la fotosíntesis.|Fan la fotosíntesi.|They photosynthesise.'),
      M('Las bacterias pertenecen al dominio…|Els bacteris pertanyen al domini…|Bacteria belong to the domain…', 'Bacteria|Bacteria|Bacteria', ['Eukarya|Eukarya|Eukarya', 'Animalia|Animalia|Animalia'], 'Son procariotas.|Són procariotes.|They are prokaryotes.'),
      M('Una ameba es un…|Una ameba és un…|An amoeba is a…', 'protozoo (protoctista)|protozou (protoctist)|protozoan (protist)', ['hongo|fong|fungus', 'animal|animal|animal'], 'Eucariota unicelular heterótrofo.|Eucariota unicel·lular heteròtrof.|A single-celled eukaryotic heterotroph.'),
      TF('Los animales son eucariotas, pluricelulares y heterótrofos.|Els animals són eucariotes, pluricel·lulars i heteròtrofs.|Animals are eukaryotic, many-celled and heterotrophic.', true, 'Y la mayoría se desplaza.|I la majoria es desplaça.|And most can move.'),
      Nq('¿Cuántos dominios hay?|Quants dominis hi ha?|How many domains are there?', 3, [5, 2, 4], 'Bacteria, Archaea y Eukarya.|Bacteria, Archaea i Eukarya.|Bacteria, Archaea and Eukarya.'),
      M('Las arqueas suelen vivir en…|Els arqueus solen viure en…|Archaea often live in…', 'ambientes extremos (aguas termales, salinas)|ambients extrems (aigües termals, salines)|extreme places (hot springs, salt pans)', ['solo dentro de animales|només dins d’animals|only inside animals', 'el espacio|l’espai|space'], 'Resisten condiciones muy duras.|Resistixen condicions molt dures.|They survive very harsh conditions.'),
    ]),
  '1E-BG-11': lesson(['Bacterias: procariotas unicelulares; muchas son beneficiosas (yogur, digestión) y algunas causan enfermedades. Hongos: levaduras (unicelulares, pan y vino), mohos y setas; descomponen la materia. Protoctistas: protozoos (ameba, paramecio) y algas.|Bacteris: procariotes unicel·lulars; molts són beneficiosos (iogurt, digestió) i alguns causen malalties. Fongs: llevats (unicel·lulars, pa i vi), floridures i bolets; descomponen la matèria. Protoctists: protozous (ameba, parameci) i algues.|Bacteria: single-celled prokaryotes; many are useful (yoghurt, digestion) and some cause disease. Fungi: yeasts (single-celled, bread and wine), moulds and mushrooms; they decompose matter. Protists: protozoa (amoeba, paramecium) and algae.'],
    '¿Qué ser vivo hace subir la masa del pan?|Quin ésser viu fa pujar la massa del pa?|Which living thing makes bread dough rise?', ['Produce CO₂ al fermentar.|Produïx CO₂ en fermentar.|It makes CO₂ by fermenting.', 'La levadura, un hongo.|El llevat, un fong.|Yeast, a fungus.'], [
      M('El yogur se fabrica gracias a…|El iogurt es fabrica gràcies a…|Yoghurt is made thanks to…', 'bacterias|bacteris|bacteria', ['algas|algues|algae', 'protozoos|protozous|protozoa'], 'Fermentan la leche.|Fermenten la llet.|They ferment milk.'),
      M('La penicilina, el primer antibiótico, se obtuvo de…|La penicil·lina, el primer antibiòtic, es va obtindre d’…|Penicillin, the first antibiotic, came from…', 'un moho|una floridura|a mould', ['una bacteria|un bacteri|a bacterium', 'un alga|una alga|an alga'], 'Fleming, 1928.|Fleming, 1928.|Fleming, 1928.'),
      TF('Todas las bacterias son perjudiciales.|Tots els bacteris són perjudicials.|All bacteria are harmful.', false, 'Muchas nos ayudan, como la flora intestinal.|Molts ens ajuden, com la flora intestinal.|Many help us, like gut bacteria.'),
      M('Las setas que vemos son…|Els bolets que veiem són…|The mushrooms we see are…', 'la parte reproductora de un hongo|la part reproductora d’un fong|the reproductive part of a fungus', ['plantas sin hojas|plantes sense fulles|plants without leaves', 'animales|animals|animals'], 'El resto vive bajo tierra (micelio).|La resta viu sota terra (miceli).|The rest lives underground (mycelium).'),
      M('El paludismo (malaria) lo causa un…|El paludisme (malària) el causa un…|Malaria is caused by a…', 'protozoo|protozou|protozoan', ['hongo|fong|fungus', 'alga|alga|alga'], 'Lo transmite un mosquito.|El transmet un mosquit.|A mosquito transmits it.'),
      M('Las algas son importantes porque…|Les algues són importants perquè…|Algae matter because…', 'producen gran parte del oxígeno del planeta|produïxen gran part de l’oxigen del planeta|they make much of the planet’s oxygen', ['causan la gripe|causen la grip|they cause flu', 'no hacen nada|no fan res|they do nothing'], 'Hacen la fotosíntesis en el mar.|Fan la fotosíntesi en la mar.|They photosynthesise in the sea.'),
    ]),
  '1E-BG-12': lesson(['Animales vertebrados (con columna): peces, anfibios, reptiles, aves y mamíferos. Invertebrados: poríferos, cnidarios, gusanos, moluscos, artrópodos (insectos, arácnidos, crustáceos, miriápodos) y equinodermos. Plantas: sin semillas (musgos, helechos) y con semillas (gimnospermas como el pino; angiospermas con flor y fruto).|Animals vertebrats (amb columna): peixos, amfibis, rèptils, ocells i mamífers. Invertebrats: porífers, cnidaris, cucs, mol·luscs, artròpodes (insectes, aràcnids, crustacis, miriàpodes) i equinoderms. Plantes: sense llavors (molses, falgueres) i amb llavors (gimnospermes com el pi; angiospermes amb flor i fruit).|Vertebrates (with a backbone): fish, amphibians, reptiles, birds and mammals. Invertebrates: sponges, cnidarians, worms, molluscs, arthropods (insects, arachnids, crustaceans, myriapods) and echinoderms. Plants: without seeds (mosses, ferns) and with seeds (gymnosperms such as pine; flowering plants with fruit).'],
    'Una araña tiene 8 patas. ¿Es un insecto?|Una aranya té 8 potes. És un insecte?|A spider has 8 legs. Is it an insect?', ['Los insectos tienen 6 patas.|Els insectes tenen 6 potes.|Insects have 6 legs.', 'No: es un arácnido.|No: és un aràcnid.|No: it is an arachnid.'], [
      M('¿Qué vertebrado tiene piel húmeda y metamorfosis?|Quin vertebrat té pell humida i metamorfosi?|Which vertebrate has moist skin and metamorphosis?', 'la rana (anfibio)|la granota (amfibi)|a frog (amphibian)', ['el lagarto (reptil)|la sargantana (rèptil)|a lizard (reptile)', 'el gorrión (ave)|el teuladí (ocell)|a sparrow (bird)'], 'De renacuajo a adulto.|De cullerot a adult.|From tadpole to adult.'),
      M('El pulpo es un…|El polp és un…|An octopus is a…', 'molusco|mol·lusc|mollusc', ['crustáceo|crustaci|crustacean', 'pez|peix|fish'], 'Cuerpo blando; algunos con concha.|Cos tou; alguns amb closca.|Soft body; some have shells.'),
      M('Una planta que tiene flores y frutos es una…|Una planta que té flors i fruits és una…|A plant with flowers and fruit is a…', 'angiosperma|angiosperma|flowering plant (angiosperm)', ['gimnosperma|gimnosperma|gymnosperm', 'helecho|falguera|fern'], 'El fruto protege la semilla.|El fruit protegix la llavor.|The fruit protects the seed.'),
      M('Los helechos se reproducen por…|Les falgueres es reproduïxen per…|Ferns reproduce by…', 'esporas|espores|spores', ['semillas|llavors|seeds', 'frutos|fruits|fruit'], 'No tienen semillas.|No tenen llavors.|They have no seeds.'),
      M('¿Qué animal es un mamífero?|Quin animal és un mamífer?|Which animal is a mammal?', 'el delfín|el dofí|a dolphin', ['el tiburón|el tauró|a shark', 'el pingüino|el pingüí|a penguin'], 'Respira aire y amamanta a sus crías.|Respira aire i alleta les cries.|It breathes air and feeds its young on milk.'),
      M('La estrella de mar es un…|L’estrela de mar és un…|A starfish is an…', 'equinodermo|equinoderm|echinoderm', ['pez|peix|fish', 'cnidario|cnidari|cnidarian'], 'Piel con espinas, simetría radial.|Pell amb espines, simetria radial.|Spiny skin, radial symmetry.'),
    ]),
  '1E-BG-13': lesson(['Una clave dicotómica sirve para identificar seres vivos: en cada paso eliges entre dos opciones opuestas (1a/1b) hasta llegar al nombre. Se basa en características observables.|Una clau dicotòmica servix per a identificar éssers vius: en cada pas tries entre dues opcions oposades (1a/1b) fins a arribar al nom. Es basa en característiques observables.|A dichotomous key helps identify living things: at each step you choose between two opposite options (1a/1b) until you reach the name. It uses features you can observe.'],
    'Clave: 1a tiene columna → 2; 1b no tiene → invertebrado. 2a tiene plumas → ave; 2b no tiene → 3. Un gorrión, ¿qué es?|Clau: 1a té columna → 2; 1b no en té → invertebrat. 2a té plomes → ocell; 2b no en té → 3. Un teuladí, què és?|Key: 1a has a backbone → 2; 1b does not → invertebrate. 2a has feathers → bird; 2b does not → 3. What is a sparrow?', ['Tiene columna: voy a 2.|Té columna: vaig al 2.|It has a backbone: go to 2.', 'Tiene plumas: ave.|Té plomes: ocell.|It has feathers: bird.'], [
      M('En una clave dicotómica, cada paso ofrece…|En una clau dicotòmica, cada pas oferix…|At each step of a dichotomous key you get…', 'dos opciones opuestas|dues opcions oposades|two opposite options', ['diez opciones|deu opcions|ten options', 'una sola opción|una sola opció|one option'], 'Di = dos.|Di = dos.|Di = two.'),
      M('Clave: 1a seis patas → insecto; 1b ocho patas → arácnido. Un escorpión tiene ocho patas:|Clau: 1a sis potes → insecte; 1b huit potes → aràcnid. Un escorpí té huit potes:|Key: 1a six legs → insect; 1b eight legs → arachnid. A scorpion has eight legs:', 'arácnido|aràcnid|arachnid', ['insecto|insecte|insect', 'crustáceo|crustaci|crustacean'], 'Sigue la opción 1b.|Seguix l’opció 1b.|Follow option 1b.'),
      TF('Las claves usan rasgos que se pueden observar, como el número de patas.|Les claus usen trets que es poden observar, com el nombre de potes.|Keys use observable features, like the number of legs.', true, 'No opiniones.|No opinions.|Not opinions.'),
      M('¿Qué característica NO sirve en una clave?|Quina característica NO servix en una clau?|Which feature is NO good in a key?', '«es bonito»|«és bonic»|"it is pretty"', ['«tiene alas»|«té ales»|"it has wings"', '«hojas con borde liso»|«fulles amb vora llisa»|"leaves with smooth edges"'], 'No es objetiva.|No és objectiva.|It is not objective.'),
      M('Clave de hojas: 1a hoja en aguja → pino; 1b hoja ancha → 2. 2a borde dentado → olmo; 2b borde liso → olivo. Hoja ancha de borde liso:|Clau de fulles: 1a fulla en agulla → pi; 1b fulla ampla → 2. 2a vora dentada → om; 2b vora llisa → olivera. Fulla ampla de vora llisa:|Leaf key: 1a needle leaf → pine; 1b broad leaf → 2. 2a toothed edge → elm; 2b smooth edge → olive. Broad leaf with a smooth edge:', 'olivo|olivera|olive', ['olmo|om|elm', 'pino|pi|pine'], '1b y después 2b.|1b i després 2b.|1b then 2b.'),
      M('En la misma clave, una hoja en forma de aguja es de…|En la mateixa clau, una fulla en forma d’agulla és de…|In the same key, a needle-shaped leaf is from…', 'pino|pi|pine', ['olivo|olivera|olive', 'olmo|om|elm'], 'Opción 1a.|Opció 1a.|Option 1a.'),
    ]),
  '1E-BG-14': lesson(['La biodiversidad es la variedad de seres vivos: de especies, de genes y de ecosistemas. Es importante porque mantiene los ecosistemas y nos da alimentos, medicinas y recursos. Se pierde por destrucción de hábitats, contaminación, especies invasoras, sobreexplotación y cambio climático.|La biodiversitat és la varietat d’éssers vius: d’espècies, de gens i d’ecosistemes. És important perquè manté els ecosistemes i ens dona aliments, medicines i recursos. Es perd per destrucció d’hàbitats, contaminació, espècies invasores, sobreexplotació i canvi climàtic.|Biodiversity is the variety of life: of species, genes and ecosystems. It matters because it keeps ecosystems working and gives us food, medicines and resources. It is lost through habitat destruction, pollution, invasive species, overexploitation and climate change.'],
    '¿Por qué importa conservar una especie poco conocida?|Per què importa conservar una espècie poc coneguda?|Why does conserving a little-known species matter?', ['Forma parte de una red de relaciones.|Forma part d’una xarxa de relacions.|It is part of a web of relationships.', 'Y puede tener usos aún desconocidos (medicinas).|I pot tindre usos encara desconeguts (medicines).|And may have uses still unknown (medicines).'], [
      M('¿Cuál es una amenaza para la biodiversidad?|Quina és una amenaça per a la biodiversitat?|Which is a threat to biodiversity?', 'las especies invasoras|les espècies invasores|invasive species', ['los parques naturales|els parcs naturals|nature reserves', 'las semillas autóctonas|les llavors autòctones|native seeds'], 'Como el cangrejo americano.|Com el cranc americà.|Like the American crayfish.'),
      M('El samaruc es un pez en peligro que vive en…|El samaruc és un peix en perill que viu en…|The samaruc is an endangered fish that lives in…', 'humedales valencianos|aiguamolls valencians|Valencian wetlands', ['el océano profundo|l’oceà profund|the deep ocean', 'los Alpes|els Alps|the Alps'], 'Endemismo de la Comunitat Valenciana y Cataluña.|Endemisme de la Comunitat Valenciana i Catalunya.|Found only in Valencia and Catalonia.'),
      TF('La biodiversidad incluye también la variedad de ecosistemas.|La biodiversitat inclou també la varietat d’ecosistemes.|Biodiversity also includes the variety of ecosystems.', true, 'Y la variedad genética.|I la varietat genètica.|And genetic variety.'),
      M('Un parque natural sirve sobre todo para…|Un parc natural servix sobretot per a…|A nature reserve mainly serves to…', 'proteger especies y hábitats|protegir espècies i hàbitats|protect species and habitats', ['construir urbanizaciones|construir urbanitzacions|build housing', 'cazar sin límite|caçar sense límit|hunt without limit'], 'Como L’Albufera o el Montgó.|Com l’Albufera o el Montgó.|Like L’Albufera or the Montgó.'),
      M('Muchos medicamentos proceden de…|Molts medicaments procedixen de…|Many medicines come from…', 'plantas y otros seres vivos|plantes i altres éssers vius|plants and other living things', ['rocas volcánicas|roques volcàniques|volcanic rocks', 'el plástico|el plàstic|plastic'], 'La biodiversidad es una farmacia.|La biodiversitat és una farmàcia.|Biodiversity is a pharmacy.'),
      TF('Soltar una tortuga de Florida en un río ayuda a la naturaleza.|Soltar una tortuga de Florida en un riu ajuda la natura.|Releasing a pet slider turtle into a river helps nature.', false, 'Es invasora y desplaza a las autóctonas.|És invasora i desplaça les autòctones.|It is invasive and pushes out native species.'),
    ]),
  '1E-BG-15': lesson(['La Tierra es el tercer planeta del Sistema Solar. Su movimiento de rotación (24 h) produce el día y la noche; el de traslación alrededor del Sol (365 días), con el eje inclinado, produce las estaciones. La Luna gira alrededor de la Tierra y causa las mareas y las fases lunares.|La Terra és el tercer planeta del Sistema Solar. El seu moviment de rotació (24 h) produïx el dia i la nit; el de translació al voltant del Sol (365 dies), amb l’eix inclinat, produïx les estacions. La Lluna gira al voltant de la Terra i causa les marees i les fases lunars.|Earth is the third planet in the Solar System. Its rotation (24 h) causes day and night; its orbit round the Sun (365 days), with its tilted axis, causes the seasons. The Moon orbits the Earth and causes tides and lunar phases.'],
    '¿Por qué en verano hace más calor?|Per què a l’estiu fa més calor?|Why is it hotter in summer?', ['No es porque estemos más cerca del Sol.|No és perquè estiguem més a prop del Sol.|It is not because we are closer to the Sun.', 'Por la inclinación del eje: los rayos llegan más directos.|Per la inclinació de l’eix: els raigs arriben més directes.|Because of the tilted axis: sunlight hits more directly.'], [
      M('El día y la noche se deben a…|El dia i la nit es deuen a…|Day and night are caused by…', 'la rotación de la Tierra|la rotació de la Terra|the Earth’s rotation', ['la traslación|la translació|its orbit', 'la Luna|la Lluna|the Moon'], 'Gira sobre sí misma en 24 h.|Gira sobre si mateixa en 24 h.|It spins once in 24 h.'),
      Nq('¿Qué lugar ocupa la Tierra por distancia al Sol?|Quin lloc ocupa la Terra per distància al Sol?|What is Earth’s position counting out from the Sun?', 3, [1, 4, 2], 'Mercurio, Venus, Tierra…|Mercuri, Venus, Terra…|Mercury, Venus, Earth…'),
      M('Las mareas se deben sobre todo a…|Les marees es deuen sobretot a…|Tides are mainly caused by…', 'la atracción de la Luna|l’atracció de la Lluna|the Moon’s pull', ['el viento|el vent|the wind', 'los terremotos|els terratrémols|earthquakes'], 'Gravedad lunar.|Gravetat lunar.|Lunar gravity.'),
      TF('El Sol es una estrella.|El Sol és una estrela.|The Sun is a star.', true, 'Tiene luz propia.|Té llum pròpia.|It makes its own light.'),
      M('¿Qué planeta es el más grande del Sistema Solar?|Quin planeta és el més gran del Sistema Solar?|Which is the largest planet in the Solar System?', 'Júpiter|Júpiter|Jupiter', ['la Tierra|la Terra|Earth', 'Marte|Mart|Mars'], 'Es un gigante gaseoso.|És un gegant gasós.|It is a gas giant.'),
      M('Un eclipse de Sol ocurre cuando…|Un eclipsi de Sol ocorre quan…|A solar eclipse happens when…', 'la Luna se pone entre el Sol y la Tierra|la Lluna es posa entre el Sol i la Terra|the Moon passes between the Sun and Earth', ['la Tierra tapa a la Luna|la Terra tapa la Lluna|the Earth covers the Moon', 'el Sol se apaga|el Sol s’apaga|the Sun switches off'], 'La sombra de la Luna llega a la Tierra.|L’ombra de la Lluna arriba a la Terra.|The Moon’s shadow falls on Earth.'),
    ]),
  '1E-BG-16': lesson(['La Tierra tiene capas. Geosfera: corteza (continental y oceánica), manto y núcleo (de hierro y níquel). Además: atmósfera (aire), hidrosfera (agua) y biosfera (seres vivos), que interaccionan entre sí.|La Terra té capes. Geosfera: escorça (continental i oceànica), mantell i nucli (de ferro i níquel). A més: atmosfera (aire), hidrosfera (aigua) i biosfera (éssers vius), que interaccionen entre si.|The Earth has layers. Geosphere: crust (continental and oceanic), mantle and core (iron and nickel). Plus the atmosphere (air), hydrosphere (water) and biosphere (living things), which interact.'],
    '¿Cuál es la capa más interna?|Quina és la capa més interna?|Which is the innermost layer?', ['Debajo del manto.|Davall del mantell.|Below the mantle.', 'El núcleo.|El nucli.|The core.'], [
      M('¿Sobre qué capa vivimos?|Sobre quina capa vivim?|Which layer do we live on?', 'la corteza|l’escorça|the crust', ['el manto|el mantell|the mantle', 'el núcleo|el nucli|the core'], 'Es la más delgada.|És la més prima.|It is the thinnest.'),
      M('El núcleo terrestre está formado sobre todo por…|El nucli terrestre està format sobretot per…|The Earth’s core is mainly…', 'hierro y níquel|ferro i níquel|iron and nickel', ['agua|aigua|water', 'granito|granit|granite'], 'Metales muy densos.|Metalls molt densos.|Very dense metals.'),
      M('La hidrosfera es…|La hidrosfera és…|The hydrosphere is…', 'toda el agua de la Tierra|tota l’aigua de la Terra|all the water on Earth', ['la capa de aire|la capa d’aire|the layer of air', 'el conjunto de seres vivos|el conjunt d’éssers vius|all living things'], 'Océanos, ríos, hielo, aguas subterráneas.|Oceans, rius, gel, aigües subterrànies.|Oceans, rivers, ice, groundwater.'),
      TF('La corteza oceánica es más delgada que la continental.|L’escorça oceànica és més prima que la continental.|Oceanic crust is thinner than continental crust.', true, 'Unos 7 km frente a 35 km o más.|Uns 7 km enfront de 35 km o més.|About 7 km against 35 km or more.'),
      M('¿Qué capa es la más gruesa de la geosfera?|Quina capa és la més grossa de la geosfera?|Which is the thickest layer of the geosphere?', 'el manto|el mantell|the mantle', ['la corteza|l’escorça|the crust', 'la atmósfera|l’atmosfera|the atmosphere'], 'Casi 2 900 km.|Quasi 2 900 km.|Almost 2,900 km.'),
      M('La biosfera está formada por…|La biosfera està formada per…|The biosphere is made up of…', 'todos los seres vivos|tots els éssers vius|all living things', ['las rocas|les roques|the rocks', 'los gases|els gasos|the gases'], 'Bio = vida.|Bio = vida.|Bio = life.'),
    ]),
  '1E-BG-17': lesson(['Un mineral es una sustancia natural, inorgánica, sólida y con composición y estructura definidas (cuarzo, calcita, halita). Una roca es un agregado de minerales. Tipos: magmáticas (granito, basalto), sedimentarias (caliza, arenisca) y metamórficas (mármol, pizarra).|Un mineral és una substància natural, inorgànica, sòlida i amb composició i estructura definides (quars, calcita, halita). Una roca és un agregat de minerals. Tipus: magmàtiques (granit, basalt), sedimentàries (calcària, gres) i metamòrfiques (marbre, pissarra).|A mineral is a natural, inorganic solid with a definite composition and structure (quartz, calcite, halite). A rock is a mixture of minerals. Types: igneous (granite, basalt), sedimentary (limestone, sandstone) and metamorphic (marble, slate).'],
    'El mármol se forma a partir de la caliza. ¿Qué tipo de roca es?|El marbre es forma a partir de la calcària. Quin tipus de roca és?|Marble forms from limestone. What type of rock is it?', ['La caliza se transforma por presión y temperatura.|La calcària es transforma per pressió i temperatura.|Limestone is changed by pressure and heat.', 'Metamórfica.|Metamòrfica.|Metamorphic.'], [
      M('El granito es una roca…|El granit és una roca…|Granite is…', 'magmática|magmàtica|igneous', ['sedimentaria|sedimentària|sedimentary', 'metamórfica|metamòrfica|metamorphic'], 'Se forma al enfriarse el magma lentamente.|Es forma en refredar-se el magma lentament.|It forms as magma cools slowly.'),
      M('¿Qué mineral es la sal común?|Quin mineral és la sal comuna?|Which mineral is rock salt?', 'halita|halita|halite', ['cuarzo|quars|quartz', 'mica|mica|mica'], 'Cloruro de sodio.|Clorur de sodi.|Sodium chloride.'),
      M('La caliza reacciona con ácido haciendo burbujas porque tiene…|La calcària reacciona amb àcid fent bombolles perquè té…|Limestone fizzes with acid because it contains…', 'calcita|calcita|calcite', ['cuarzo|quars|quartz', 'oro|or|gold'], 'Carbonato de calcio.|Carbonat de calci.|Calcium carbonate.'),
      M('En la escala de Mohs, el mineral más duro es…|En l’escala de Mohs, el mineral més dur és…|On the Mohs scale, the hardest mineral is…', 'el diamante (10)|el diamant (10)|diamond (10)', ['el talco (1)|el talc (1)|talc (1)', 'el yeso (2)|el guix (2)|gypsum (2)'], 'Raya a todos los demás.|Ratlla tots els altres.|It scratches all the others.'),
      TF('Las rocas sedimentarias pueden contener fósiles.|Les roques sedimentàries poden contindre fòssils.|Sedimentary rocks can contain fossils.', true, 'Se forman por capas de sedimentos.|Es formen per capes de sediments.|They form in layers of sediment.'),
      M('Una roca es…|Una roca és…|A rock is…', 'un conjunto de minerales|un conjunt de minerals|a mixture of minerals', ['siempre un solo mineral|sempre un sol mineral|always one mineral', 'un ser vivo|un ésser viu|a living thing'], 'El granito tiene cuarzo, feldespato y mica.|El granit té quars, feldspat i mica.|Granite has quartz, feldspar and mica.'),
    ]),
  '1E-BG-18': lesson(['El interior de la Tierra está caliente. Esa energía interna mueve las placas tectónicas y produce volcanes, terremotos y la formación de montañas. Los terremotos se miden con sismógrafos; los volcanes expulsan lava, gases y piroclastos.|L’interior de la Terra està calent. Eixa energia interna mou les plaques tectòniques i produïx volcans, terratrémols i la formació de muntanyes. Els terratrémols es mesuren amb sismògrafs; els volcans expulsen lava, gasos i piroclasts.|The Earth’s interior is hot. This internal energy moves tectonic plates and causes volcanoes, earthquakes and mountain building. Earthquakes are measured with seismographs; volcanoes erupt lava, gases and pyroclasts.'],
    '¿Por qué hay muchos volcanes en Japón?|Per què hi ha molts volcans al Japó?|Why are there many volcanoes in Japan?', ['Está en el límite entre placas.|Està en el límit entre plaques.|It lies on a plate boundary.', 'Allí sube magma con facilidad.|Allà puja magma amb facilitat.|Magma rises easily there.'], [
      M('El punto del interior donde se origina un terremoto es el…|El punt de l’interior on s’origina un terratrémol és l’…|The point underground where an earthquake starts is the…', 'hipocentro|hipocentre|focus', ['epicentro|epicentre|epicentre', 'cráter|cràter|crater'], 'El epicentro está en la superficie, encima.|L’epicentre està en la superfície, damunt.|The epicentre is on the surface above it.'),
      M('La roca fundida que sale de un volcán es…|La roca fosa que ix d’un volcà és…|Molten rock coming out of a volcano is…', 'lava|lava|lava', ['granito|granit|granite', 'arena|arena|sand'], 'Dentro de la Tierra se llama magma.|Dins de la Terra es diu magma.|Underground it is called magma.'),
      TF('Los terremotos y volcanes se concentran en los bordes de las placas.|Els terratrémols i volcans es concentren en les vores de les plaques.|Earthquakes and volcanoes cluster at plate edges.', true, 'Allí chocan o se separan.|Allà xoquen o se separen.|That is where plates collide or separate.'),
      M('Un tsunami es…|Un tsunami és…|A tsunami is…', 'una gran ola causada por un terremoto submarino|una gran ona causada per un terratrémol submarí|a huge wave caused by an undersea earthquake', ['un viento fuerte|un vent fort|a strong wind', 'una lluvia de cenizas|una pluja de cendres|a shower of ash'], 'Puede cruzar océanos.|Pot creuar oceans.|It can cross oceans.'),
      M('Los Pirineos se formaron por…|Els Pirineus es van formar per…|The Pyrenees formed because…', 'el choque de dos placas|el xoc de dues plaques|two plates collided', ['un meteorito|un meteorit|a meteorite', 'la erosión del viento|l’erosió del vent|wind erosion'], 'Placas ibérica y euroasiática.|Plaques ibèrica i euroasiàtica.|The Iberian and Eurasian plates.'),
      M('El instrumento que registra terremotos es el…|L’instrument que registra terratrémols és el…|The instrument that records earthquakes is a…', 'sismógrafo|sismògraf|seismograph', ['barómetro|baròmetre|barometer', 'termómetro|termòmetre|thermometer'], 'Seísmo = terremoto.|Sisme = terratrémol.|Seismic = earthquake.'),
    ]),
  '1E-BG-19': lesson(['Los agentes geológicos externos (agua, viento, hielo, seres vivos) modelan el relieve: meteorización (rompen las rocas), erosión (las desgastan), transporte y sedimentación (depositan los materiales). Los ríos forman valles en V; los glaciares, valles en U.|Els agents geològics externs (aigua, vent, gel, éssers vius) modelen el relleu: meteorització (trenquen les roques), erosió (les desgasten), transport i sedimentació (dipositen els materials). Els rius formen valls en V; les glaceres, valls en U.|External agents (water, wind, ice, living things) shape the land: weathering (breaking rocks), erosion (wearing them away), transport and deposition (laying down material). Rivers carve V-shaped valleys; glaciers, U-shaped ones.'],
    '¿Qué es un delta, como el del Ebro?|Què és un delta, com el de l’Ebre?|What is a delta, like the Ebro delta?', ['El río pierde fuerza al llegar al mar.|El riu perd força en arribar a la mar.|The river slows as it reaches the sea.', 'Deposita sedimentos: sedimentación.|Diposita sediments: sedimentació.|It drops sediment: deposition.'], [
      M('El agua que se congela en las grietas rompe las rocas. Es…|L’aigua que es congela en les esquerdes trenca les roques. És…|Water freezing in cracks breaks rocks. This is…', 'meteorización (gelifracción)|meteorització (gelifracció)|weathering (freeze-thaw)', ['sedimentación|sedimentació|deposition', 'vulcanismo|vulcanisme|volcanic activity'], 'El hielo ocupa más que el agua.|El gel ocupa més que l’aigua.|Ice takes up more space than water.'),
      M('Un valle en forma de U lo forma…|Una vall en forma d’U la forma…|A U-shaped valley is formed by…', 'un glaciar|una glacera|a glacier', ['un río|un riu|a river', 'el viento|el vent|the wind'], 'El hielo excava un valle ancho.|El gel excava una vall ampla.|Ice carves a wide valley.'),
      M('Las dunas del desierto las forma…|Les dunes del desert les forma…|Desert dunes are made by…', 'el viento|el vent|the wind', ['el hielo|el gel|ice', 'los terremotos|els terratrémols|earthquakes'], 'Transporta y deposita arena.|Transporta i diposita arena.|It carries and drops sand.'),
      TF('Las raíces de los árboles pueden romper rocas.|Les arrels dels arbres poden trencar roques.|Tree roots can break rocks.', true, 'Meteorización biológica.|Meteorització biològica.|Biological weathering.'),
      M('Las cuevas en rocas calizas se forman por…|Les coves en roques calcàries es formen per…|Caves in limestone form by…', 'disolución por el agua|dissolució per l’aigua|water dissolving the rock', ['viento|vent|wind', 'volcanes|volcans|volcanoes'], 'Relieve kárstico.|Relleu càrstic.|Karst landscape.'),
      M('Ordena el proceso:|Ordena el procés:|Put the process in order:', 'erosión, transporte, sedimentación|erosió, transport, sedimentació|erosion, transport, deposition', ['sedimentación, erosión, transporte|sedimentació, erosió, transport|deposition, erosion, transport', 'transporte, sedimentación, erosión|transport, sedimentació, erosió|transport, deposition, erosion'], 'Se arranca, se lleva y se deposita.|S’arranca, es porta i es diposita.|Removed, carried, dropped.'),
    ]),
  '1E-BG-20': lesson(['Atmósfera: protege, regula la temperatura y permite respirar. Capas: troposfera (tiempo atmosférico), estratosfera (capa de ozono)… Hidrosfera: el 97 % del agua es salada; la dulce está sobre todo en hielos y acuíferos. El ciclo del agua: evaporación, condensación, precipitación, escorrentía e infiltración.|Atmosfera: protegix, regula la temperatura i permet respirar. Capes: troposfera (temps atmosfèric), estratosfera (capa d’ozó)… Hidrosfera: el 97 % de l’aigua és salada; la dolça està sobretot en gels i aqüífers. El cicle de l’aigua: evaporació, condensació, precipitació, escolament i infiltració.|Atmosphere: protects, regulates temperature and lets us breathe. Layers: troposphere (weather), stratosphere (ozone layer)… Hydrosphere: 97% of water is salty; fresh water is mainly in ice and aquifers. The water cycle: evaporation, condensation, precipitation, runoff and infiltration.'],
    '¿Cómo llega el agua del mar a las montañas?|Com arriba l’aigua de la mar a les muntanyes?|How does seawater get to the mountains?', ['Se evapora y forma nubes.|S’evapora i forma núvols.|It evaporates and forms clouds.', 'Llueve o nieva en las montañas.|Plou o neva a les muntanyes.|It falls as rain or snow on the mountains.'], [
      Nq('¿Qué porcentaje del agua de la Tierra es salada (aprox.)?|Quin percentatge de l’aigua de la Terra és salada (aprox.)?|About what percentage of Earth’s water is salty?', 97, [50, 3, 70], 'Casi toda.|Quasi tota.|Almost all of it.'),
      M('El agua que penetra en el suelo hasta los acuíferos sufre…|L’aigua que penetra en el sòl fins als aqüífers patix…|Water soaking into the ground to aquifers undergoes…', 'infiltración|infiltració|infiltration', ['evaporación|evaporació|evaporation', 'condensación|condensació|condensation'], 'Forma aguas subterráneas.|Forma aigües subterrànies.|It forms groundwater.'),
      M('¿Dónde está la mayor parte del agua dulce?|On està la major part de l’aigua dolça?|Where is most fresh water?', 'en los hielos polares y glaciares|en els gels polars i glaceres|in polar ice and glaciers', ['en los ríos|en els rius|in rivers', 'en las nubes|en els núvols|in clouds'], 'Los ríos tienen muy poca.|Els rius en tenen molt poca.|Rivers hold very little.'),
      M('La capa de ozono está en la…|La capa d’ozó està en l’…|The ozone layer is in the…', 'estratosfera|estratosfera|stratosphere', ['troposfera|troposfera|troposphere', 'hidrosfera|hidrosfera|hydrosphere'], 'Entre unos 15 y 50 km de altura.|Entre uns 15 i 50 km d’altura.|About 15 to 50 km up.'),
      TF('El Sol es el motor del ciclo del agua.|El Sol és el motor del cicle de l’aigua.|The Sun drives the water cycle.', true, 'Su energía evapora el agua.|La seua energia evapora l’aigua.|Its energy evaporates water.'),
      M('La «gota fría» (DANA) en la Comunitat Valenciana provoca…|La «gota freda» (DANA) a la Comunitat Valenciana provoca…|A "cold drop" (DANA) in the Valencia region brings…', 'lluvias torrenciales|pluges torrencials|torrential rain', ['nevadas en la costa en verano|nevades a la costa a l’estiu|summer snow on the coast', 'sequía extrema inmediata|sequera extrema immediata|instant extreme drought'], 'Sobre todo en otoño, con el mar caliente.|Sobretot a la tardor, amb la mar calenta.|Mainly in autumn, with a warm sea.'),
    ]),
  '1E-BG-21': lesson(['La Tierra tiene unos 4 600 millones de años. El tiempo geológico se divide en eones, eras y periodos. Los fósiles y el principio de superposición (las capas de abajo son más antiguas) permiten ordenar los acontecimientos.|La Terra té uns 4 600 milions d’anys. El temps geològic es dividix en eons, eres i períodes. Els fòssils i el principi de superposició (les capes de baix són més antigues) permeten ordenar els esdeveniments.|The Earth is about 4.6 billion years old. Geological time is divided into eons, eras and periods. Fossils and the principle of superposition (lower layers are older) let us put events in order.'],
    'En un corte, la capa A está debajo de la B. ¿Cuál es más antigua?|En un tall, la capa A està davall de la B. Quina és més antiga?|In a rock face, layer A is below layer B. Which is older?', ['Las capas se depositan unas sobre otras.|Les capes es dipositen unes sobre altres.|Layers are laid down on top of each other.', 'A es más antigua.|A és més antiga.|A is older.'], [
      M('Los dinosaurios vivieron en la era…|Els dinosaures van viure en l’era…|Dinosaurs lived in the…', 'Mesozoica|Mesozoica|Mesozoic era', ['Cenozoica|Cenozoica|Cenozoic era', 'Precámbrica|Precambriana|Precambrian'], 'Se extinguieron hace 66 millones de años.|Es van extingir fa 66 milions d’anys.|They died out 66 million years ago.'),
      M('Un fósil es…|Un fòssil és…|A fossil is…', 'un resto o huella de un ser vivo antiguo conservado en la roca|una resta o empremta d’un ésser viu antic conservat en la roca|remains or traces of an ancient living thing preserved in rock', ['un mineral brillante|un mineral brillant|a shiny mineral', 'una roca volcánica|una roca volcànica|a volcanic rock'], 'Como conchas, huesos o huellas.|Com petxines, ossos o petjades.|Like shells, bones or footprints.'),
      TF('Los seres humanos convivieron con los dinosaurios.|Els éssers humans van conviure amb els dinosaures.|Humans lived alongside dinosaurs.', false, 'Nos separan más de 60 millones de años.|Ens separen més de 60 milions d’anys.|Over 60 million years separate us.'),
      M('Vivimos en la era…|Vivim en l’era…|We live in the…', 'Cenozoica|Cenozoica|Cenozoic era', ['Paleozoica|Paleozoica|Palaeozoic era', 'Mesozoica|Mesozoica|Mesozoic era'], 'La «era de los mamíferos».|L’«era dels mamífers».|The "age of mammals".'),
      Nq('¿Cuántos millones de años tiene la Tierra (aprox.)?|Quants milions d’anys té la Terra (aprox.)?|About how many million years old is the Earth?', 4600, [6000, 460, 46], 'Unos 4 600 millones.|Uns 4 600 milions.|About 4,600 million.'),
      M('Un fósil guía sirve para…|Un fòssil guia servix per a…|An index fossil is used to…', 'datar las rocas donde aparece|datar les roques on apareix|date the rocks it is found in', ['encontrar petróleo seguro|trobar petroli segur|guarantee finding oil', 'medir terremotos|mesurar terratrémols|measure earthquakes'], 'Vivió poco tiempo y en muchos lugares.|Va viure poc de temps i en molts llocs.|It lived briefly but widely.'),
    ]),
  '1E-BG-22': lesson(['La geosfera nos da recursos: minerales, rocas de construcción, combustibles fósiles, agua subterránea y suelo. Riesgos geológicos: terremotos, volcanes, inundaciones, deslizamientos. Se reducen con prevención: mapas de riesgo, edificios adecuados, no construir en cauces.|La geosfera ens dona recursos: minerals, roques de construcció, combustibles fòssils, aigua subterrània i sòl. Riscos geològics: terratrémols, volcans, inundacions, esllavissades. Es reduïxen amb prevenció: mapes de risc, edificis adequats, no construir en llits de rius.|The geosphere provides resources: minerals, building stone, fossil fuels, groundwater and soil. Geological hazards: earthquakes, volcanoes, floods, landslides. Prevention reduces them: hazard maps, suitable buildings, not building in riverbeds.'],
    '¿Por qué no hay que construir en un barranco seco?|Per què no s’ha de construir en un barranc sec?|Why shouldn’t you build in a dry ravine?', ['Con lluvias fuertes se llena de agua.|Amb pluges fortes s’ompli d’aigua.|Heavy rain fills it with water.', 'Riesgo de inundación.|Risc d’inundació.|Flood risk.'], [
      M('El carbón y el petróleo son recursos…|El carbó i el petroli són recursos…|Coal and oil are…', 'no renovables|no renovables|non-renewable resources', ['renovables|renovables|renewable resources', 'infinitos|infinits|infinite resources'], 'Tardan millones de años en formarse.|Tarden milions d’anys a formar-se.|They take millions of years to form.'),
      TF('Los edificios antisísmicos reducen daños en terremotos.|Els edificis antisísmics reduïxen danys en terratrémols.|Earthquake-proof buildings reduce damage.', true, 'Prevención.|Prevenció.|Prevention.'),
      M('El mármol y la piedra caliza se usan sobre todo en…|El marbre i la pedra calcària s’usen sobretot en…|Marble and limestone are mainly used in…', 'construcción|construcció|building', ['alimentación|alimentació|food', 'medicina|medicina|medicine'], 'Fachadas, suelos, cemento.|Façanes, sòls, ciment.|Facades, floors, cement.'),
      M('Un mapa de riesgos sirve para…|Un mapa de riscos servix per a…|A hazard map is used to…', 'saber dónde no conviene construir|saber on no convé construir|know where not to build', ['predecir el día exacto de un terremoto|predir el dia exacte d’un terratrémol|predict the exact day of an earthquake', 'buscar oro|buscar or|look for gold'], 'Planificar el territorio.|Planificar el territori.|Land planning.'),
      TF('El suelo fértil tarda muchísimo en formarse.|El sòl fèrtil tarda moltíssim a formar-se.|Fertile soil takes a very long time to form.', true, 'Siglos para unos centímetros.|Segles per a uns centímetres.|Centuries for a few centimetres.'),
      M('Ante un terremoto dentro de casa, lo más seguro es…|Davant d’un terratrémol dins de casa, el més segur és…|During an earthquake indoors, the safest thing is to…', 'protegerse bajo una mesa resistente|protegir-se davall d’una taula resistent|take cover under a sturdy table', ['bajar en ascensor|baixar amb ascensor|take the lift', 'asomarse a la ventana|abocar-se a la finestra|lean out of the window'], 'Agacharse, cubrirse y agarrarse.|Ajupir-se, cobrir-se i agafar-se.|Drop, cover and hold on.'),
    ]),
  '1E-BG-23': lesson(['Un ecosistema está formado por el biotopo (medio físico: agua, suelo, clima) y la biocenosis (seres vivos). Relaciones: depredación, competencia, parasitismo, mutualismo, comensalismo.|Un ecosistema està format pel biòtop (medi físic: aigua, sòl, clima) i la biocenosi (éssers vius). Relacions: depredació, competència, parasitisme, mutualisme, comensalisme.|An ecosystem is made up of the habitat (physical environment: water, soil, climate) and the community (living things). Relationships: predation, competition, parasitism, mutualism, commensalism.'],
    'Las abejas toman néctar y polinizan las flores. ¿Qué relación es?|Les abelles prenen nèctar i pol·linitzen les flors. Quina relació és?|Bees take nectar and pollinate flowers. What relationship is it?', ['Los dos se benefician.|Tots dos se’n beneficien.|Both benefit.', 'Mutualismo.|Mutualisme.|Mutualism.'], [
      M('Una garrapata en un perro es un ejemplo de…|Una paparra en un gos és un exemple de…|A tick on a dog is an example of…', 'parasitismo|parasitisme|parasitism', ['mutualismo|mutualisme|mutualism', 'competencia|competència|competition'], 'Uno se beneficia y el otro sale perjudicado.|Un se’n beneficia i l’altre n’ix perjudicat.|One benefits, the other is harmed.'),
      M('El biotopo incluye…|El biòtop inclou…|The habitat (biotope) includes…', 'el agua, el suelo y el clima|l’aigua, el sòl i el clima|water, soil and climate', ['los animales|els animals|the animals', 'las plantas|les plantes|the plants'], 'Lo no vivo.|El que no és viu.|The non-living part.'),
      M('Dos zorros que pelean por la misma presa muestran…|Dues raboses que es barallen per la mateixa presa mostren…|Two foxes fighting over the same prey show…', 'competencia|competència|competition', ['mutualismo|mutualisme|mutualism', 'comensalismo|comensalisme|commensalism'], 'Recursos limitados.|Recursos limitats.|Limited resources.'),
      TF('L’Albufera es un ecosistema de humedal.|L’Albufera és un ecosistema d’aiguamoll.|L’Albufera is a wetland ecosystem.', true, 'Lago, arrozales y dunas.|Llac, arrossars i dunes.|Lake, rice fields and dunes.'),
      M('La biocenosis es…|La biocenosi és…|The community (biocenosis) is…', 'el conjunto de seres vivos del ecosistema|el conjunt d’éssers vius de l’ecosistema|all the living things in the ecosystem', ['el tipo de suelo|el tipus de sòl|the type of soil', 'la temperatura|la temperatura|the temperature'], 'Bio = vida.|Bio = vida.|Bio = life.'),
      M('Un búho que caza ratones es…|Un mussol que caça ratolins és…|An owl hunting mice is…', 'depredación|depredació|predation', ['parasitismo|parasitisme|parasitism', 'mutualismo|mutualisme|mutualism'], 'Depredador y presa.|Depredador i presa.|Predator and prey.'),
    ]),
  '1E-BG-24': lesson(['En el ecosistema, la materia hace un ciclo (productores → consumidores → descomponedores → suelo → productores) y la energía fluye en una sola dirección: entra como luz y se pierde como calor en cada nivel. Por eso las cadenas tienen pocos eslabones.|En l’ecosistema, la matèria fa un cicle (productors → consumidors → descomponedors → sòl → productors) i l’energia flueix en una sola direcció: entra com a llum i es perd com a calor en cada nivell. Per això les cadenes tenen poques baules.|In an ecosystem, matter cycles (producers → consumers → decomposers → soil → producers) while energy flows one way: it enters as light and is lost as heat at each level. That is why food chains are short.'],
    '¿Por qué hay menos lobos que conejos?|Per què hi ha menys llops que conills?|Why are there fewer wolves than rabbits?', ['En cada nivel solo pasa un 10 % de la energía.|En cada nivell només passa un 10 % de l’energia.|Only about 10% of energy passes up each level.', 'Arriba hay menos energía para mantener individuos.|A dalt hi ha menys energia per a mantindre individus.|There is less energy at the top to support animals.'], [
      M('¿Qué seres devuelven la materia al suelo?|Quins éssers tornen la matèria al sòl?|Which organisms return matter to the soil?', 'descomponedores|descomponedors|decomposers', ['productores|productors|producers', 'herbívoros|herbívors|herbivores'], 'Hongos y bacterias.|Fongs i bacteris.|Fungi and bacteria.'),
      TF('La energía se recicla en el ecosistema igual que la materia.|L’energia es recicla en l’ecosistema igual que la matèria.|Energy is recycled in an ecosystem just like matter.', false, 'La energía fluye y se pierde como calor.|L’energia flueix i es perd com a calor.|Energy flows through and is lost as heat.'),
      Nq('Si los productores tienen 10 000 unidades de energía, ¿cuántas llegan a los herbívoros (regla del 10 %)?|Si els productors tenen 10 000 unitats d’energia, quantes arriben als herbívors (regla del 10 %)?|If producers have 10,000 units of energy, how many reach the herbivores (10% rule)?', 1000, [100, 10000, 5000], '10 % de 10 000.|10 % de 10 000.|10% of 10,000.'),
      M('Una red trófica es…|Una xarxa tròfica és…|A food web is…', 'varias cadenas alimentarias conectadas|diverses cadenes alimentàries connectades|several linked food chains', ['un solo eslabón|una sola baula|a single link', 'una trampa para insectos|una trampa per a insectes|an insect trap'], 'Más real que una cadena.|Més real que una cadena.|More realistic than a chain.'),
      M('La energía entra en el ecosistema como…|L’energia entra en l’ecosistema com a…|Energy enters an ecosystem as…', 'luz del sol|llum del sol|sunlight', ['calor de la Tierra|calor de la Terra|heat from the Earth', 'agua|aigua|water'], 'La captan los productores.|La capten els productors.|Producers capture it.'),
      M('El ciclo del carbono: las plantas toman CO₂ y los seres vivos lo devuelven al…|El cicle del carboni: les plantes prenen CO₂ i els éssers vius el tornen en…|Carbon cycle: plants take in CO₂ and living things give it back by…', 'respirar|respirar|respiring', ['beber|beure|drinking', 'dormir|dormir|sleeping'], 'Y al descomponerse o quemarse.|I en descompondre’s o cremar-se.|And by decaying or burning.'),
    ]),
  '1E-BG-25': lesson(['Problemas ambientales: cambio climático (por gases de efecto invernadero), contaminación del aire, del agua y del suelo, residuos plásticos, pérdida de biodiversidad, sobreexplotación de recursos y desertificación.|Problemes ambientals: canvi climàtic (per gasos d’efecte d’hivernacle), contaminació de l’aire, de l’aigua i del sòl, residus plàstics, pèrdua de biodiversitat, sobreexplotació de recursos i desertificació.|Environmental problems: climate change (from greenhouse gases), air, water and soil pollution, plastic waste, biodiversity loss, overuse of resources and desertification.'],
    '¿Qué causa principalmente el cambio climático actual?|Què causa principalment el canvi climàtic actual?|What mainly causes current climate change?', ['Quema de combustibles fósiles.|Crema de combustibles fòssils.|Burning fossil fuels.', 'Aumento de CO₂ y otros gases de efecto invernadero.|Augment de CO₂ i altres gasos d’efecte d’hivernacle.|More CO₂ and other greenhouse gases.'], [
      M('La desertificación es…|La desertificació és…|Desertification is…', 'la pérdida de suelo fértil en zonas secas|la pèrdua de sòl fèrtil en zones seques|the loss of fertile soil in dry areas', ['que llueve mucho|que plou molt|heavy rainfall', 'un tipo de nieve|un tipus de neu|a kind of snow'], 'Un riesgo en el sureste peninsular.|Un risc en el sud-est peninsular.|A risk in south-east Spain.'),
      TF('Los plásticos tardan cientos de años en degradarse.|Els plàstics tarden centenars d’anys a degradar-se.|Plastics take hundreds of years to break down.', true, 'Se acumulan en mares y playas.|S’acumulen en mars i platges.|They build up in seas and on beaches.'),
      M('¿Qué gas es el principal responsable del efecto invernadero añadido por los humanos?|Quin gas és el principal responsable de l’efecte d’hivernacle afegit pels humans?|Which gas is mainly responsible for the extra greenhouse effect from humans?', 'CO₂|CO₂|CO₂', ['O₂|O₂|O₂', 'N₂|N₂|N₂'], 'Dióxido de carbono.|Diòxid de carboni.|Carbon dioxide.'),
      M('La contaminación por nitratos de los acuíferos viene sobre todo de…|La contaminació per nitrats dels aqüífers ve sobretot de…|Nitrate pollution of aquifers mainly comes from…', 'el exceso de abonos en la agricultura|l’excés d’adobs en l’agricultura|too much fertiliser in farming', ['los volcanes|els volcans|volcanoes', 'la lluvia limpia|la pluja neta|clean rain'], 'El agua los arrastra al subsuelo.|L’aigua els arrossega al subsòl.|Water carries them underground.'),
      TF('Talar bosques aumenta el CO₂ de la atmósfera.|Talar boscos augmenta el CO₂ de l’atmosfera.|Cutting down forests increases atmospheric CO₂.', true, 'Hay menos árboles que lo absorban.|Hi ha menys arbres que l’absorbisquen.|Fewer trees absorb it.'),
      M('Una consecuencia del cambio climático en el Mediterráneo es…|Una conseqüència del canvi climàtic en la Mediterrània és…|A consequence of climate change in the Mediterranean is…', 'más olas de calor y sequías|més onades de calor i sequeres|more heatwaves and droughts', ['inviernos más largos y fríos|hiverns més llargs i freds|longer, colder winters', 'menos temperatura del mar|menys temperatura de la mar|cooler seas'], 'Y episodios de lluvia más intensos.|I episodis de pluja més intensos.|And more intense rainfall events.'),
    ]),
  '1E-BG-26': lesson(['Los Objetivos de Desarrollo Sostenible (ODS) son 17 metas de la ONU para 2030: acabar con la pobreza y el hambre, salud, educación de calidad, igualdad de género, agua limpia, energía asequible y no contaminante, acción por el clima, vida submarina, vida de ecosistemas terrestres…|Els Objectius de Desenvolupament Sostenible (ODS) són 17 metes de l’ONU per a 2030: acabar amb la pobresa i la fam, salut, educació de qualitat, igualtat de gènere, aigua neta, energia assequible i no contaminant, acció pel clima, vida submarina, vida d’ecosistemes terrestres…|The Sustainable Development Goals (SDGs) are 17 UN targets for 2030: end poverty and hunger, health, quality education, gender equality, clean water, affordable clean energy, climate action, life below water, life on land…'],
    '¿Con qué ODS se relaciona plantar árboles autóctonos?|Amb quin ODS es relaciona plantar arbres autòctons?|Which SDG is planting native trees linked to?', ['Protege ecosistemas terrestres.|Protegix ecosistemes terrestres.|It protects ecosystems on land.', 'ODS 15: vida de ecosistemas terrestres (y 13, clima).|ODS 15: vida d’ecosistemes terrestres (i 13, clima).|SDG 15: life on land (and 13, climate).'], [
      Nq('¿Cuántos ODS hay?|Quants ODS hi ha?|How many SDGs are there?', 17, [10, 20, 12], 'Aprobados por la ONU en 2015.|Aprovats per l’ONU el 2015.|Agreed by the UN in 2015.'),
      M('Recoger plásticos de una playa ayuda sobre todo al ODS…|Arreplegar plàstics d’una platja ajuda sobretot a l’ODS…|Picking up plastic on a beach mainly helps SDG…', '14: vida submarina|14: vida submarina|14: life below water', ['4: educación|4: educació|4: education', '8: trabajo decente|8: treball decent|8: decent work'], 'Los plásticos acaban en el mar.|Els plàstics acaben en la mar.|Plastics end up in the sea.'),
      M('El ODS 6 trata de…|L’ODS 6 tracta de…|SDG 6 is about…', 'agua limpia y saneamiento|aigua neta i sanejament|clean water and sanitation', ['energía nuclear|energia nuclear|nuclear energy', 'viajes espaciales|viatges espacials|space travel'], 'Acceso al agua para todos.|Accés a l’aigua per a tots.|Water for everyone.'),
      TF('Los ODS solo dependen de los gobiernos; las personas no pueden hacer nada.|Els ODS només depenen dels governs; les persones no poden fer res.|The SDGs depend only on governments; individuals can do nothing.', false, 'Cada gesto suma: consumo, transporte, reciclaje.|Cada gest suma: consum, transport, reciclatge.|Every action counts: shopping, transport, recycling.'),
      M('Usar el transporte público ayuda al ODS…|Usar el transport públic ajuda a l’ODS…|Using public transport helps SDG…', '13: acción por el clima|13: acció pel clima|13: climate action', ['2: hambre cero|2: fam zero|2: zero hunger', '5: igualdad de género|5: igualtat de gènere|5: gender equality'], 'Menos emisiones.|Menys emissions.|Fewer emissions.'),
      M('Los ODS forman parte de la Agenda…|Els ODS formen part de l’Agenda…|The SDGs are part of the Agenda…', '2030|2030|2030', ['2000|2000|2000', '2100|2100|2100'], 'El año objetivo.|L’any objectiu.|The target year.'),
    ]),
  '1E-BG-27': lesson(['Proteger el medio ambiente: reducir, reutilizar y reciclar (3 R), ahorrar agua y energía, consumir productos locales y de temporada, moverse a pie, en bici o en transporte público, y proteger espacios naturales.|Protegir el medi ambient: reduir, reutilitzar i reciclar (3 R), estalviar aigua i energia, consumir productes locals i de temporada, moure’s a peu, en bici o en transport públic, i protegir espais naturals.|Protecting the environment: reduce, reuse and recycle (the 3 Rs), save water and energy, buy local seasonal food, walk, cycle or use public transport, and protect natural areas.'],
    '¿Cuál de las 3 R es la más importante?|Quina de les 3 R és la més important?|Which of the 3 Rs matters most?', ['Lo que no se produce no hay que reciclarlo.|El que no es produïx no cal reciclar-ho.|What is never made needs no recycling.', 'Reducir.|Reduir.|Reduce.'], [
      M('¿En qué contenedor va una botella de plástico?|En quin contenidor va una botella de plàstic?|Which bin does a plastic bottle go in?', 'amarillo|groc|the yellow bin', ['azul|blau|the blue bin', 'verde|verd|the green bin'], 'Envases.|Envasos.|Packaging.'),
      M('¿En qué contenedor va el papel y el cartón?|En quin contenidor va el paper i el cartó?|Which bin is for paper and cardboard?', 'azul|blau|the blue bin', ['amarillo|groc|the yellow bin', 'marrón|marró|the brown bin'], 'Papel y cartón.|Paper i cartó.|Paper and card.'),
      M('Los restos de comida van al contenedor…|Les restes de menjar van al contenidor…|Food scraps go in the…', 'marrón (orgánico)|marró (orgànic)|brown bin (organic)', ['azul|blau|blue bin', 'verde (vidrio)|verd (vidre)|green bin (glass)'], 'Se convierten en compost.|Es convertixen en compost.|They become compost.'),
      TF('Comer fruta de temporada y cercana reduce emisiones de transporte.|Menjar fruita de temporada i propera reduïx emissions de transport.|Eating local, seasonal fruit cuts transport emissions.', true, 'Kilómetro cero.|Quilòmetre zero.|Food miles.'),
      M('Reutilizar es…|Reutilitzar és…|Reusing means…', 'usar de nuevo un objeto|usar de nou un objecte|using something again', ['tirarlo al contenedor|tirar-lo al contenidor|throwing it in a bin', 'comprar uno nuevo|comprar-ne un de nou|buying a new one'], 'Por ejemplo, una botella rellenable.|Per exemple, una botella reomplible.|For example, a refillable bottle.'),
      M('Las pilas usadas se llevan…|Les piles usades es porten…|Used batteries should go…', 'a un punto de recogida específico|a un punt de recollida específic|to a special collection point', ['al contenedor amarillo|al contenidor groc|in the yellow bin', 'a la basura normal|al fem normal|in the general rubbish'], 'Contienen metales tóxicos.|Contenen metalls tòxics.|They contain toxic metals.'),
    ]),
};
export default P;
